CREATE FUNCTION techerp_api.inbox_runtime_release_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN IF NEW.entity='inbox_channel_occurrences' AND (NEW.enabled OR NEW.status='published') THEN RAISE EXCEPTION 'Gatilhos multicanal ainda em revisão: produtores, provas, destinatários e validações precisam ser concluídos antes da ativação.' USING ERRCODE='42501';END IF;RETURN NEW;END $$; REVOKE ALL ON FUNCTION techerp_api.inbox_runtime_release_guard() FROM PUBLIC,anon,authenticated,service_role; CREATE TRIGGER inbox_runtime_release_guard BEFORE INSERT OR UPDATE ON public.workflows FOR EACH ROW EXECUTE FUNCTION techerp_api.inbox_runtime_release_guard(); COMMENT ON FUNCTION techerp_api.inbox_runtime_release_guard() IS 'Release lock for incomplete CANAIS-ATENDIMENTO draft. Do not remove until authenticated end-to-end producers, recipient reuse, proof-current, RLS/JWT regression and all project gates pass.'; NOTIFY pgrst,'reload schema';
